import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel that fuses addition and multiplication with y
fused_add_mul_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_add_mul_kernel(const float* x, const float* y, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // Compute (x + y) * y in a single fused kernel
        out[idx] = (x[idx] + y[idx]) * y[idx];
    }
}

torch::Tensor fused_add_mul_cuda(torch::Tensor x, torch::Tensor y) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_add_mul_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), y.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

fused_add_mul_cpp_source = "torch::Tensor fused_add_mul_cuda(torch::Tensor x, torch::Tensor y);"

# Compile the fused kernel
fused_add_mul = load_inline(
    name="fused_add_mul",
    cpp_sources=fused_add_mul_cpp_source,
    cuda_sources=fused_add_mul_source,
    functions=["fused_add_mul_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces the final addition and multiplication
    with a fused custom CUDA kernel.
    """
    def __init__(self, in_features, out_features, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.bmm = nn.Linear(in_features, out_features)
        self.instance_norm = nn.InstanceNorm2d(out_features, eps=eps, momentum=momentum)

    def forward(self, x, y):
        x = self.bmm(x)
        x = self.instance_norm(x.unsqueeze(2).unsqueeze(3)).squeeze(3).squeeze(2)
        # Fused (x + y) * y operation
        x = fused_add_mul.fused_add_mul_cuda(x, y)
        return x

batch_size = 128
in_features = 64
out_features = 128

def get_inputs():
    return [
        torch.randn(batch_size, in_features).cuda(),
        torch.randn(batch_size, out_features).cuda()
    ]

def get_init_inputs():
    return [in_features, out_features]
